import Foundation
import SwiftUI
import UIKit

/// Bundled MF Workouts data (read-only, generated by `scripts/catalog.ts`) merged with the owner's custom exercises.
@MainActor @Observable
final class ExerciseCatalog {
    private(set) var bundled: [Exercise]
    private var byID: [ExerciseID: Exercise]
    private(set) var custom: [Exercise] = []
    let equipment: [String: Equipment]
    let articles: [String: Article]

    init() {
        let decoded: [Exercise] = Self.load("exercises")
        bundled = decoded.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        byID = Dictionary(uniqueKeysWithValues: decoded.map { ($0.id, $0) })
        equipment = Dictionary(uniqueKeysWithValues: (Self.load("equipment") as [Equipment]).map { ($0.id, $0) })
        articles = Dictionary(uniqueKeysWithValues: (Self.load("articles") as [Article]).map { ($0.id, $0) })
    }

    private static func load<T: Decodable>(_ name: String) -> T {
        guard let url = Bundle.main.url(forResource: name, withExtension: "json") else {
            fatalError("Missing \(name).json. Regenerate it with `bun app-ios/scripts/catalog.ts`.")
        }
        do {
            return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
        } catch {
            fatalError("\(name).json does not match its Swift type: \(error)")
        }
    }

    /// Markdown with "Setting up", "Exercise technique", and "Description" sections.
    func instructions(for exercise: Exercise) -> String? {
        exercise.hasInstructions ? Self.markdown(exercise.id) : nil
    }

    func articleText(_ article: Article) -> String? { Self.markdown(article.id) }

    private static func markdown(_ name: String) -> String? {
        Bundle.main.url(forResource: name, withExtension: "md").flatMap { try? String(contentsOf: $0, encoding: .utf8) }
    }

    var all: [Exercise] { custom + bundled }

    /// Called by the app whenever the `CustomExercise` store changes.
    func setCustom(_ exercises: [Exercise]) {
        for old in custom { byID[old.id] = nil }
        custom = exercises
        for exercise in exercises { byID[exercise.id] = exercise }
    }

    func exercise(_ id: ExerciseID) -> Exercise? { byID[id] }

    /// Name for display even when an ID no longer resolves, so history never shows a blank row.
    func name(_ id: ExerciseID) -> String { byID[id]?.name ?? "Unknown exercise" }
}

/// One of an exercise's position frames from the bundle, or a muscle-colored placeholder.
struct ExerciseImage: View {
    let exercise: Exercise
    var frame = 0

    var body: some View {
        if let image = Self.load(exercise.images[safe: frame]) {
            Image(uiImage: image).resizable().scaledToFill()
        } else {
            ZStack {
                Theme.surfaceRaised
                Image(systemName: "figure.strengthtraining.traditional")
                    .font(.system(size: 24))
                    .foregroundStyle(Theme.textTertiary)
            }
        }
    }

    private static let cache = NSCache<NSString, UIImage>()

    private static func load(_ name: String?) -> UIImage? {
        guard let name else { return nil }
        if let hit = cache.object(forKey: name as NSString) { return hit }
        guard let url = Bundle.main.url(forResource: name, withExtension: "webp"),
              let image = UIImage(contentsOfFile: url.path) else { return nil }
        cache.setObject(image, forKey: name as NSString)
        return image
    }
}

extension Array {
    subscript(safe index: Int) -> Element? { indices.contains(index) ? self[index] : nil }
}
